import { Table, StringColumn, BooleanColumn, ReferenceColumn } from '../../db'

export const sys_ws_query_parameter = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Scripted REST Query Parameter',
    name: 'sys_ws_query_parameter',
    schema: {
        example_value: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'An example of a valid value for this query parameter. Appears in API documentation.',
                    label: 'Example value',
                    plural: 'Example values',
                },
            ],
            maxLength: 255,
        }),
        short_description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The description of the query parameter. Appears in API documentation.',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 80,
        }),
        required: BooleanColumn({
            label: [
                {
                    hint: 'Require this query parameter in all requests to the resource',
                    label: 'Is required',
                    plural: 'Is required',
                },
            ],
            maxLength: 30,
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The name of the query parameter. Appears in API documentation.',
                    label: 'Query parameter name',
                    plural: 'Query parameter names',
                },
            ],
            mandatory: true,
        }),
        web_service_definition: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The API this query parameter belongs to',
                    label: 'API definition',
                    plural: 'API definitions',
                },
            ],
            mandatory: true,
            referenceTable: 'sys_ws_definition',
        }),
    },
    textIndex: true,
})
